ALTER TABLE users ADD COLUMN permissions text DEFAULT '', ADD COLUMN force_password_change integer DEFAULT 0;
CREATE TABLE user_roles(name text PRIMARY KEY,permissions text);
INSERT INTO user_roles VALUES('manager','employees,manage_employees,attendance,manage_attendance,shifts,manage_shifts,leave,manage_leave,employee_documents,employee_performance');
CREATE TABLE employees(id serial PRIMARY KEY,employee_no text UNIQUE NOT NULL,user_id integer UNIQUE REFERENCES users(id),full_name text NOT NULL,phone text,address text,date_of_birth text,national_id text,photo_path text,photo_data bytea,hire_date text NOT NULL,position text,department text,branch text,employment_status text DEFAULT 'Active',zkteco_user_id text,emergency_contact_name text,emergency_contact_phone text,notes text,created_at timestamp DEFAULT CURRENT_TIMESTAMP,updated_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shifts(id serial PRIMARY KEY,name text UNIQUE NOT NULL,start_time text NOT NULL,end_time text NOT NULL,break_minutes integer DEFAULT 0,is_overnight integer DEFAULT 0,is_active integer DEFAULT 1,created_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_shifts(id serial PRIMARY KEY,employee_id integer REFERENCES employees(id),shift_id integer REFERENCES shifts(id),effective_from text NOT NULL,effective_to text,weekly_off_days text,created_at timestamp DEFAULT CURRENT_TIMESTAMP,UNIQUE(employee_id,effective_from));
CREATE TABLE attendance(id serial PRIMARY KEY,employee_id integer REFERENCES employees(id),attendance_date text NOT NULL,check_in text,check_out text,status text DEFAULT 'Present',late_minutes integer DEFAULT 0,notes text,corrected_by integer,correction_reason text,created_at timestamp DEFAULT CURRENT_TIMESTAMP,updated_at timestamp DEFAULT CURRENT_TIMESTAMP,UNIQUE(employee_id,attendance_date));
CREATE TABLE expenses(id serial PRIMARY KEY,expense_no text UNIQUE NOT NULL,category text,description text,amount float8,expense_date text,payment_method text,created_by text,notes text);
CREATE TABLE payrolls(id serial PRIMARY KEY,payroll_no text UNIQUE NOT NULL,employee_id integer REFERENCES employees(id),period_month text NOT NULL,basic_salary float8 DEFAULT 0,allowance float8 DEFAULT 0,overtime_amount float8 DEFAULT 0,bonus float8 DEFAULT 0,late_deduction float8 DEFAULT 0,absence_deduction float8 DEFAULT 0,advance_deduction float8 DEFAULT 0,other_deduction float8 DEFAULT 0,net_salary float8 DEFAULT 0,status text DEFAULT 'Draft',paid_date text,payment_method text,expense_id integer REFERENCES expenses(id),notes text,created_by integer,created_at timestamp DEFAULT CURRENT_TIMESTAMP,UNIQUE(employee_id,period_month));
CREATE TABLE employee_leave(id serial PRIMARY KEY,employee_id integer REFERENCES employees(id),leave_type text NOT NULL,start_date text NOT NULL,end_date text NOT NULL,days float8 DEFAULT 1,reason text,status text DEFAULT 'Pending',reviewed_by integer,reviewed_at timestamp,review_notes text,created_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_documents(id serial PRIMARY KEY,employee_id integer REFERENCES employees(id),document_type text NOT NULL,document_no text,file_path text,issued_date text,expiry_date text,notes text,created_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE salary_advances(id serial PRIMARY KEY,employee_id integer REFERENCES employees(id),advance_date text NOT NULL,amount float8 NOT NULL,repaid_amount float8 DEFAULT 0,status text DEFAULT 'Outstanding',notes text,created_by integer,created_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE commission_rules(id serial PRIMARY KEY,employee_id integer UNIQUE REFERENCES employees(id),rate_percent float8 DEFAULT 0,target_amount float8 DEFAULT 0,active integer DEFAULT 1,updated_at timestamp DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cash_sessions(id serial PRIMARY KEY,employee_id integer REFERENCES employees(id),opened_at timestamp NOT NULL,opening_cash float8 DEFAULT 0,closed_at timestamp,expected_cash float8,actual_cash float8,difference float8,status text DEFAULT 'Open',notes text,opened_by integer,closed_by integer);
